-- Aquagram — 0063: Glaser karşılaştırması 1. parti — 56 yeni tür (+ varyete/lokaliteler, makale bağlantıları)
-- Görsel numaraları: 818–873 (scripts/gorsel-numaralari.json)

-- Yeni kategori: Afrika Nehir Cichlidleri (Orta Amerika'dan sonra)
update public.kb_categories set position = position + 1 where position >= 5 and id <> 'afrika-nehir';
insert into public.kb_categories (id, section, name, emoji, tone, position)
values ('afrika-nehir', 'tatlisu', 'Afrika Nehir Cichlidleri', '🌴', 'from-lime-300 to-orange-600', 5)
on conflict (id) do nothing;

insert into public.species (slug, name, latin, category_id, kind, difficulty, temperament, description, facts, keywords, is_rare, care_notice, range_areas, name_note, status)
values
('carassius-auratus','Japon Balığı','Carassius auratus','sazangiller','fish','Kolay','Barışçıl, grup hâlinde','Çin''de bin yılı aşkın seçilimle evcilleştirilmiş, dünyanın en bilinen akvaryum balığı. Comet, Oranda, Ranchu, Teleskop gibi onlarca formu vardır. Fanus efsanesinin aksine geniş hacim, güçlü filtre ve serin su ister; çok yem yer ve suyu hızla kirletir.','[["Yetişkin boy", "15–30 cm (süslü formlar 15–20 cm)"], ["Sıcaklık", "10–24 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "100 L (süslü form çifti); tek kuyruklular için havuz"], ["Huy", "Barışçıl, grup hâlinde"], ["Beslenme", "Hepçil: batan pelet, haşlanmış sebze, kan kurdu"], ["Üreme", "Yumurtlayan (yumurtaları bitkilere saçar)"], ["Köken", "Doğu Asya (Çin) — evcil form"], ["Ömür", "10–20 yıl (daha uzun da yaşayabilir)"], ["Özellikler", "Soğuk su, çok sayıda form"]]'::jsonb,array['japon balığı','kırmızı balık','goldfish','carassius','carassius auratus','oranda','ranchu','comet','teleskop','japon']::text[],false,'Fanus ve küçük kaplar uygun değildir. Tropikal balıklarla aynı tankta tutulmamalı; süslü formlar hızlı yüzen comet ve shubunkinlerle de yemde yarışamaz. Doğaya, göle ya da dereye asla bırakılmamalıdır (istilacıdır).','[{"r": 900, "lat": 30, "lng": 113, "label": "Doğu Çin (evcilleştirildiği bölge)"}]'::jsonb,null,'published'),
('tropheus-duboisi','Duboisi (Beyaz Benekli Tropheus)','Tropheus duboisi','tanganyika','fish','Orta','Tür içi saldırgan, kalabalık grup','Yavrularken siyah zemin üzerindeki beyaz beneklerle, erişkinken siyah gövde ve sarı-beyaz bir bantla tanınan Tanganyika Tropheus''u. Kayalardaki algle beslenen otçul bir balıktır; protein ağırlıklı yemler ölümcül "bloat" hastalığına yol açar.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "250 L"], ["Huy", "Tür içi saldırgan; 10+ bireylik grup"], ["Beslenme", "Otçul: spirulina ve sebze ağırlıklı yem"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Tanzanya, Tanganyika Gölü kuzeydoğu kıyıları"], ["Ömür", "8–12 yıl"], ["Özellikler", "Yavru ve erişkin desenleri tamamen farklı"]]'::jsonb,array['duboisi','tropheus duboisi','beyaz benekli tropheus','white spotted cichlid','tropheus','maswa']::text[],false,'Bloat riski yüksektir: kan kurdu ve protein ağırlıklı yemlerden kaçın, az ve sık besle. Çift ya da küçük grup hâlinde tutulursa baskın birey diğerlerini öldürebilir.','[{"r": 150, "lat": -5.2, "lng": 29.8, "label": "Tanganyika Gölü kuzeydoğu (Kigoma çevresi)"}]'::jsonb,null,'published'),
('apistogramma-elizabethae','Elizabeth Cüce Cichlid','Apistogramma elizabethae','guney-amerika','fish','Zor','Barışçıl, harem','Rio Negro''nun çok yumuşak ve asidik siyah sularından, erkekleri mavi-kırmızı yüz deseni ve yüksek sırt yüzgeciyle dikkat çeken nadir bir cüce cichlid. Su değerlerine hassastır; deneyimli bakıcılar içindir.','[["Yetişkin boy", "Erkek 6–8 cm, dişi 4–5 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "4.5–6.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 1 erkek + 2–3 dişi"], ["Beslenme", "Etçil: canlı ve donuk küçük yemler"], ["Üreme", "Mağarada yumurtlayan; yavrulara dişi bakar"], ["Köken", "Brezilya, yukarı Rio Negro"], ["Ömür", "4–6 yıl"], ["Özellikler", "Siyah su, çok yumuşak su"]]'::jsonb,array['elizabeth','elizabethae','apistogramma elizabethae','elizabeth cüce cichlid','apisto','apistogramma']::text[],true,'Yumuşak (GH 1–3), asidik su ve düzenli küçük su değişimleri şart. Ani değer değişimlerine çok duyarlıdır.','[{"r": 250, "lat": -0.2, "lng": -66.9, "label": "Yukarı Rio Negro (São Gabriel da Cachoeira çevresi)"}]'::jsonb,null,'published'),
('ivanacara-adoketa','Zebra Acara','Ivanacara adoketa','guney-amerika','fish','Orta','Barışçıl, çift hâlinde','Gövdesindeki siyah dikey bantlar ve erkeklerin sırt yüzgecindeki uzun ipliklerle zebrayı andıran küçük bir acara. Yumuşak, asidik suyu sever ve sakin topluluk akvaryumlarına uyum sağlar.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–6.8"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl; üremede bölgeci"], ["Beslenme", "Hepçil: granül, donuk ve canlı küçük yemler"], ["Üreme", "Yumurtlayan (düz taş ya da mağara); çift bakar"], ["Köken", "Brezilya, yukarı Rio Negro havzası"], ["Ömür", "5–8 yıl"], ["Özellikler", "Bantlı desen, uzun sırt yüzgeci iplikleri"]]'::jsonb,array['zebra acara','ivanacara adoketa','nannacara adoketa','adoketa','ivanacara','acara']::text[],false,'','[{"r": 250, "lat": 0.3, "lng": -67.5, "label": "Yukarı Rio Negro havzası"}]'::jsonb,'Eski adı Nannacara adoketa; hobide hâlâ bu adla da geçer.','published'),
('teleocichla-centrarchus','Teleocichla centrarchus','Teleocichla centrarchus','guney-amerika','fish','Zor','Tür içi bölgeci','Xingu Nehri''nin hızlı akıntılı kayalık bölümlerine uyum sağlamış, ince uzun gövdeli bir cüce cichlid. Güçlü akıntı, yüksek oksijen ve çok temiz su ister; kaya aralarında yaşar.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "26–30 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "120 L (uzun tank)"], ["Huy", "Tür içi bölgeci; diğer türlerle barışçıl"], ["Beslenme", "Etçil: küçük omurgasızlar, donuk yemler"], ["Üreme", "Mağarada yumurtlayan"], ["Köken", "Brezilya, Rio Xingu"], ["Ömür", "5–8 yıl"], ["Özellikler", "Reofilik (akıntı sever)"]]'::jsonb,array['teleocichla','teleocichla centrarchus','centrarchus','xingu cichlid']::text[],true,'Güçlü akıntı pompası ve yüksek oksijen şart; durgun suda kısa sürede hastalanır.','[{"r": 300, "lat": -3.5, "lng": -52.2, "label": "Rio Xingu (Altamira çevresi)"}]'::jsonb,null,'published'),
('tetraodon-schoutedeni','Kongo Benekli Balonu','Tetraodon schoutedeni','diger-baliklar','fish','Orta','Diğer balıkların yüzgeçlerini ısırabilir','Kongo Nehri''nin aşağı havzasından, sarımsı gövdesi koyu beneklerle kaplı küçük bir balon. Satışta "tatlı su" denen birçok balonun aksine gerçekten tamamen tatlı suda yaşar ve tuz istemez.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Yalnız ya da tür içi grup; yüzgeç ısırabilir"], ["Beslenme", "Etçil: salyangoz, karides, kan kurdu"], ["Üreme", "Yumurtlayan (yumurtaları erkek bekler)"], ["Köken", "KDC, aşağı Kongo Nehri (Kinshasa çevresi)"], ["Ömür", "5–10 yıl"], ["Özellikler", "Tamamen tatlı su, salyangoz yer"]]'::jsonb,array['kongo balonu','congo spotted puffer','congo puffer','tetraodon schoutedeni','schoutedeni','balon balığı','puffer']::text[],false,'Gagası sürekli uzadığı için salyangoz gibi sert kabuklu yemlerle aşınması gerekir.','[{"r": 250, "lat": -4.6, "lng": 15.2, "label": "Aşağı Kongo Nehri"}]'::jsonb,null,'published'),
('carinotetraodon-irrubesco','Kırmızı Gözlü Kırmızı Kuyruklu Balon','Carinotetraodon irrubesco','diger-baliklar','fish','Orta','Tür içi bölgeci','Sumatra ve Borneo''nun tatlı sularından, pea puffer''dan biraz daha iri, erkeklerinde kırmızı kuyruk ve karın çizgisi bulunan küçük bir balon. Kırmızı gözleri ve meraklı davranışıyla bilinir.','[["Yetişkin boy", "4–6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Tür içi bölgeci; tek tür tank önerilir"], ["Beslenme", "Etçil: salyangoz, kan kurdu, artemia"], ["Üreme", "Yumurtlayan; erkek yumurtaları bekler"], ["Köken", "Endonezya (Sumatra, Kalimantan)"], ["Ömür", "4–5 yıl"], ["Özellikler", "Tatlı su, kırmızı gözler"]]'::jsonb,array['red eye red tail puffer','kırmızı gözlü balon','carinotetraodon irrubesco','irrubesco','balon balığı','puffer']::text[],false,'Gagasının aşınması için salyangoz şart. Diğer balıkların yüzgeçlerini ısırır.','[{"r": 350, "lat": -1.5, "lng": 103.5, "label": "Sumatra"}, {"r": 300, "lat": -1, "lng": 112, "label": "Kalimantan"}]'::jsonb,null,'published'),
('etroplus-canarensis','Canara Pearlspot','Etroplus canarensis','diger-baliklar','fish','Zor','Barışçıl, grup hâlinde','Hindistan''ın Batı Ghat dağlarındaki temiz ve hızlı akan nehirlere özgü, tamamen tatlı suda yaşayan bir Etroplus. Gövdesindeki koyu bantlar ve sarı tonlarıyla tanınır; doğada nesli tehlike altındadır ve hobide nadir bulunur.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: alg, küçük omurgasızlar, granül"], ["Üreme", "Yumurtlayan; çift bakar"], ["Köken", "Hindistan, Karnataka (Batı Ghat''lar)"], ["Ömür", "6–10 yıl"], ["Özellikler", "Tatlı su, yüksek oksijen"]]'::jsonb,array['canara pearlspot','etroplus canarensis','canarensis','etroplus','banded pearlspot']::text[],true,'Doğada nesli tehlike altındadır; yalnızca üretim bireyleri tercih edilmeli. Akıntılı, oksijeni bol su ister.','[{"r": 150, "lat": 12.8, "lng": 75.4, "label": "Batı Ghat''lar (Karnataka)"}]'::jsonb,null,'published'),
('amphiprion-percula','Gerçek Palyaço Balığı (True Percula)','Amphiprion percula','deniz-baliklari','fish','Orta','Çift hâlinde, yuvasını korur','Ocellaris''e çok benzeyen ama beyaz bantlarının çevresinde daha kalın siyah çizgiler bulunan palyaço balığı. Doğada anemonla ortak yaşar; akvaryum üretimi bireyler anemon olmadan da rahatça yaşar.','[["Yetişkin boy", "8–11 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.1–8.4"], ["Min. akvaryum", "100 L"], ["Huy", "Çift hâlinde; yuvasını korur"], ["Beslenme", "Hepçil: deniz peleti, artemia, mysis"], ["Üreme", "Yumurtlayan; yumurtaları erkek bakar"], ["Köken", "Kuzey Avustralya, Yeni Gine ve Melanezya"], ["Ömür", "15–20 yıl"], ["Özellikler", "Cinsiyet değiştirir (erkekten dişiye)"]]'::jsonb,array['true percula','percula','amphiprion percula','palyaço balığı','clownfish','nemo','anemon balığı']::text[],false,'Ocellaris ile karıştırılır: percula''da beyaz bantların siyah kenarları kalın, gözün iris kısmı turuncudur.','[{"r": 900, "lat": -6, "lng": 150, "label": "Yeni Gine ve Melanezya"}, {"r": 500, "lat": -14, "lng": 144, "label": "Kuzey Queensland"}]'::jsonb,null,'published'),
('pelvicachromis-pulcher','Krib (Kribensis)','Pelvicachromis pulcher','afrika-nehir','fish','Kolay','Üreme döneminde bölgeci','Mor-pembe karın lekesiyle tanınan, Batı Afrika kökenli cüce cichlid; dişileri erkeklerden daha renklidir. Çift oluşturup mağarada yumurtlar ve yavrularını sürü hâlinde gezdirir; başlangıç için en uygun cichlidlerden biridir.','[["Yetişkin boy", "Erkek 8–10 cm, dişi 6–7 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; üremede bölgeci"], ["Beslenme", "Hepçil: granül, donuk yem, sebze"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "Nijerya ve Kamerun kıyı nehirleri"], ["Ömür", "5 yıl"], ["Özellikler", "Dişisi renkli, ebeveyn bakımı"]]'::jsonb,array['krib','kribensis','pelvicachromis pulcher','pelvicachromis','kribi','rainbow krib','mor karınlı cichlid']::text[],false,'Yavru dönemi dışında barışçıldır; üreme sırasında dip balıklarını kovalar. Hindistan cevizi kabuğu ya da küçük mağara sağla.','[{"r": 300, "lat": 5.3, "lng": 6.5, "label": "Güney Nijerya"}]'::jsonb,'Hobide "kribensis" adı yaygın kullanılır ama Pelvicachromis kribensis ayrı bir türdür.','published'),
('pelvicachromis-taeniatus','Pelvicachromis taeniatus','Pelvicachromis taeniatus','afrika-nehir','fish','Orta','Üreme döneminde bölgeci','Batı Afrika''nın yumuşak, asidik sularından, her lokalitesi farklı renk deseni taşıyan bir Pelvicachromis. Hobide lokalite adlarıyla satılır; farklı lokaliteler birbirine karıştırılmamalıdır.','[["Yetişkin boy", "Erkek 7–9 cm, dişi 5–6 cm"], ["Sıcaklık", "23–26 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; üremede bölgeci"], ["Beslenme", "Hepçil: donuk ve canlı küçük yemler, granül"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "Nijerya ve Kamerun"], ["Ömür", "5 yıl"], ["Özellikler", "Lokaliteye göre değişen renk"]]'::jsonb,array['taeniatus','pelvicachromis taeniatus','pelvicachromis','krib','striped kribensis']::text[],false,'','[{"r": 350, "lat": 4, "lng": 9.8, "label": "Güneybatı Kamerun ve güneydoğu Nijerya"}]'::jsonb,null,'published'),
('pelvicachromis-kribensis','Pelvicachromis kribensis','Pelvicachromis kribensis','afrika-nehir','fish','Orta','Üreme döneminde bölgeci','Uzun süre P. taeniatus''un bir formu sayılan, bugün ayrı tür olarak kabul edilen Kamerun Pelvicachromis''i. Kribi kasabası çevresindeki nehirlere özgüdür; Kienke ve Lobe gibi lokalite formlarıyla bilinir.','[["Yetişkin boy", "Erkek 7–9 cm, dişi 5–6 cm"], ["Sıcaklık", "23–26 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; üremede bölgeci"], ["Beslenme", "Hepçil: donuk ve canlı küçük yemler"], ["Üreme", "Mağarada yumurtlayan; çift bakar"], ["Köken", "Kamerun, Kribi çevresi"], ["Ömür", "5 yıl"], ["Özellikler", "Lokaliteye göre değişen renk"]]'::jsonb,array['pelvicachromis kribensis','kribensis','kienke','lobe','pelvicachromis']::text[],false,'','[{"r": 100, "lat": 2.9, "lng": 9.95, "label": "Kribi çevresi (Kamerun)"}]'::jsonb,'Uzun süre Pelvicachromis taeniatus''un bir formu sayıldı; bazı kaynaklarda hâlâ "taeniatus Kienke" gibi adlarla geçer. Hobide Krib olarak bilinen P. pulcher ile karıştırılmamalıdır.','published'),
('hemichromis-guttatus','Mücevher Ciklit (Jewel Cichlid)','Hemichromis guttatus','afrika-nehir','fish','Kolay','Üremede çok saldırgan','Parlak kırmızı gövdesi üzerindeki mavi, parıltılı beneklerle tanınan Batı Afrika ciklidi. Hobide "jewel cichlid" adıyla satılan balıkların çoğu bu türdür. Ebeveyn bakımı mükemmeldir ama üreme döneminde çok saldırganlaşır.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.5–8.0"], ["Min. akvaryum", "120 L"], ["Huy", "Saldırgan; tek çift"], ["Beslenme", "Hepçil, etçil ağırlıklı: granül, donuk yem"], ["Üreme", "Yumurtlayan (düz taş); çift bakar"], ["Köken", "Batı Afrika (Gana–Nijerya kıyı nehirleri)"], ["Ömür", "5–8 yıl"], ["Özellikler", "Parlak kırmızı renk, mavi benekler"]]'::jsonb,array['jewel cichlid','mücevher ciklit','hemichromis guttatus','hemichromis','rubricatochromis guttatus','kırmızı jewel']::text[],false,'Üreme döneminde aynı tanktaki diğer balıklara ciddi zarar verebilir; tek çift olarak ya da büyük tankta tutulmalı.','[{"r": 400, "lat": 7, "lng": 1.5, "label": "Gana, Togo, Benin kıyı nehirleri"}]'::jsonb,'Kırmızı Hemichromis türleri son revizyonla Rubricatochromis cinsine taşındı; güncel kaynaklarda Rubricatochromis guttatus olarak geçebilir. Hobide H. bimaculatus ve H. lifalili ile sık karıştırılır.','published'),
('mikrogeophagus-altispinosus','Bolivya Ramirezi','Mikrogeophagus altispinosus','guney-amerika','fish','Kolay','Barışçıl','Ramirezi''nin Bolivya-Brezilya sınırındaki kuzeni; ondan daha iri, daha dayanıklı ve daha geniş su değerlerine uyumludur. Kumu ağzıyla eleyerek beslenir; topluluk akvaryumlarına çok uygundur.','[["Yetişkin boy", "8–9 cm"], ["Sıcaklık", "22–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Açık yüzeye yumurtlayan; çift bakar"], ["Köken", "Bolivya ve Brezilya (Rio Mamoré, Rio Guaporé)"], ["Ömür", "4–6 yıl"], ["Özellikler", "Kum eleyen, dayanıklı"]]'::jsonb,array['bolivya ramirezi','bolivian ram','mikrogeophagus altispinosus','altispinosus','ramirezi','cüce cichlid']::text[],false,'','[{"r": 400, "lat": -13, "lng": -64, "label": "Rio Mamoré ve Rio Guaporé havzası"}]'::jsonb,null,'published'),
('heros-severus','Severum (Bantlı Severum)','Heros severus','guney-amerika','fish','Kolay','Barışçıl–orta','Gövdesindeki belirgin koyu bantlarla tanınan iri bir Heros. Hobide "severum" adıyla satılan balıkların çoğu aslında H. efasciatus''tur; gerçek H. severus Rio Negro ve Orinoco havzasında yaşar.','[["Yetişkin boy", "20 cm"], ["Sıcaklık", "24–29 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl–orta; üremede bölgeci"], ["Beslenme", "Hepçil: granül, sebze, donuk yem"], ["Üreme", "Yumurtlayan (düz yüzey); çift bakar"], ["Köken", "Kolombiya, Venezuela, Brezilya (Orinoco, Rio Negro)"], ["Ömür", "10–15 yıl"], ["Özellikler", "Bitki yiyebilir"]]'::jsonb,array['severum','heros severus','banded severum','severus','heros']::text[],false,'Yumuşak su bitkilerini yer; dayanıklı bitkiler ya da bitkisiz düzen tercih edilmeli.','[{"r": 500, "lat": 3, "lng": -66, "label": "Orinoco ve Rio Negro havzası"}]'::jsonb,'Hobide bu adla satılan balıkların çoğu Heros efasciatus''tur.','published'),
('symphysodon-discus','Heckel Diskus','Symphysodon discus','guney-amerika','fish','Zor','Barışçıl, grup hâlinde','Gövdesinin ortasındaki kalın siyah "Heckel bandı" ile tanınan, Rio Negro''nun siyah sularına özgü diskus. Diğer diskuslardan daha hassas ve çekingendir; çok yumuşak, asidik ve sıcak su ister.','[["Yetişkin boy", "15–20 cm"], ["Sıcaklık", "28–31 °C"], ["pH", "4.5–6.0"], ["Min. akvaryum", "300 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Etçil: donuk yemler, diskus granülü"], ["Üreme", "Yumurtlayan; yavrular ebeveynin deri salgısıyla beslenir"], ["Köken", "Brezilya, Rio Negro ve Rio Trombetas"], ["Ömür", "10–15 yıl"], ["Özellikler", "Heckel bandı, siyah su"]]'::jsonb,array['heckel diskus','heckel discus','symphysodon discus','diskus','discus','heckel']::text[],false,'Yumuşak su, yüksek sıcaklık ve sık su değişimi şart. Üretim diskuslarına göre çok daha hassastır.','[{"r": 400, "lat": -1, "lng": -63, "label": "Rio Negro"}, {"r": 200, "lat": -1, "lng": -56, "label": "Rio Trombetas"}]'::jsonb,null,'published'),
('metriaclima-callainos','Kobalt Zebra (Cobalt Blue Zebra)','Metriaclima callainos','malawi','fish','Kolay','Saldırgan (mbuna)','Tamamen kobalt mavisi ya da beyazımsı formlarıyla bilinen bir mbuna. Hobide en kolay bulunan Malawi ciklitlerinden biridir; algle kaplı kayalardan beslenir.','[["Yetişkin boy", "12 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–8.6"], ["Min. akvaryum", "200 L"], ["Huy", "Saldırgan; 1 erkek + birkaç dişi"], ["Beslenme", "Otçul ağırlıklı: spirulina, sebze bazlı yem"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Malawi Gölü kuzeybatı kıyısı"], ["Ömür", "8–10 yıl"], ["Özellikler", "Kaya balığı (mbuna)"]]'::jsonb,array['cobalt zebra','kobalt zebra','metriaclima callainos','maylandia callainos','callainos','mbuna','cobalt blue']::text[],false,'','[{"r": 80, "lat": -11.6, "lng": 34.3, "label": "Nkhata Bay çevresi"}]'::jsonb,'Birçok kaynakta Maylandia callainos olarak geçer (Metriaclima ve Maylandia adları tartışmalıdır).','published'),
('aulonocara-maylandi','Sulfurhead Peacock','Aulonocara maylandi','malawi','fish','Orta','Erkekler arası bölgeci','Erkeklerinde parlak sarı-beyaz baş ve mavi gövdeyle bilinen bir Aulonocara; "Sulphur Head" adıyla satılır. Kumda saklanan omurgasızları yanal çizgisindeki duyu çukurlarıyla bulur.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "7.8–8.6"], ["Min. akvaryum", "200 L"], ["Huy", "Erkekler arası bölgeci; mbunalarla tutulmamalı"], ["Beslenme", "Etçil: küçük omurgasızlar, granül"], ["Üreme", "Ağızda kuluçka (dişi)"], ["Köken", "Malawi Gölü doğu kıyısı"], ["Ömür", "8–10 yıl"], ["Özellikler", "Sarı baş, kum üzerinde avlanır"]]'::jsonb,array['sulfurhead','sulphur head','aulonocara maylandi','maylandi','peacock','aulonocara']::text[],false,'','[{"r": 120, "lat": -12.3, "lng": 34.8, "label": "Malawi Gölü doğu kıyısı"}]'::jsonb,null,'published'),
('nannacara-anomala','Altın Akara (Golden Dwarf Acara)','Nannacara anomala','guney-amerika','fish','Kolay','Barışçıl','Erkeği metalik yeşil-altın, dişisi üreme döneminde siyah-beyaz damalı desene bürünen küçük bir acara. Dişi erkekten çok küçük olduğundan saklanabileceği yerler mutlaka bulunmalıdır.','[["Yetişkin boy", "Erkek 8 cm, dişi 5 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; üremede dişi bölgeci"], ["Beslenme", "Hepçil: granül, donuk ve canlı küçük yemler"], ["Üreme", "Yumurtlayan (taş ya da mağara); dişi bakar"], ["Köken", "Guyana ve Surinam"], ["Ömür", "5–8 yıl"], ["Özellikler", "Dişi üremede renk değiştirir"]]'::jsonb,array['nannacara','nannacara anomala','golden dwarf acara','altın akara','anomala','acara']::text[],false,'','[{"r": 300, "lat": 5.5, "lng": -57, "label": "Guyana ve Surinam kıyı nehirleri"}]'::jsonb,null,'published'),
('dicrossus-maculatus','Benekli Dama Ciklit','Dicrossus maculatus','guney-amerika','fish','Zor','Barışçıl, harem','Checkerboard ciklidin (D. filamentosus) yakın akrabası; gövdesindeki dama deseni ve erkeklerin kırmızı-mavi yüzgeçleriyle dikkat çeker. Çok yumuşak, asidik su ister.','[["Yetişkin boy", "Erkek 7 cm, dişi 5 cm"], ["Sıcaklık", "26–29 °C"], ["pH", "4.5–6.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 1 erkek + 2 dişi"], ["Beslenme", "Etçil: canlı ve donuk küçük yemler"], ["Üreme", "Yaprak üstüne yumurtlayan; dişi bakar"], ["Köken", "Brezilya, Amazon havzası"], ["Ömür", "3–5 yıl"], ["Özellikler", "Siyah su, dama deseni"]]'::jsonb,array['dicrossus maculatus','maculatus','checkerboard','dama ciklit','dicrossus']::text[],true,'','[{"r": 400, "lat": -3, "lng": -55, "label": "Aşağı Amazon havzası"}]'::jsonb,null,'published'),
('laetacara-araguaiae','Araguaia Gülen Akara','Laetacara araguaiae','guney-amerika','fish','Kolay','Barışçıl','Ağzının çevresindeki "gülümseme" çizgisiyle tanınan Laetacara cinsinin Araguaia Nehri''nden gelen türü. Turuncu-mavi tonları ve sakin yapısıyla topluluk akvaryumlarına uygundur.','[["Yetişkin boy", "7–8 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Yumurtlayan (düz yüzey); çift bakar"], ["Köken", "Brezilya, Rio Araguaia"], ["Ömür", "5–7 yıl"], ["Özellikler", "Gülümseyen yüz deseni"]]'::jsonb,array['laetacara araguaiae','araguaiae','smiling acara','gülen akara','laetacara']::text[],false,'','[{"r": 400, "lat": -10, "lng": -50, "label": "Rio Araguaia havzası"}]'::jsonb,null,'published'),
('apistogramma-trifasciata','Üç Bantlı Apistogramma','Apistogramma trifasciata','guney-amerika','fish','Orta','Barışçıl, harem','Erkeklerinde yüksek, sivri sırt yüzgeci ve gövde boyunca uzanan koyu bantlarla tanınan küçük bir Apistogramma. Paraguay–Paraná havzasında yaşar; diğer apistolara göre daha sert suyu tolere eder.','[["Yetişkin boy", "Erkek 5–6 cm, dişi 4 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "54 L"], ["Huy", "Barışçıl; 1 erkek + 2–3 dişi"], ["Beslenme", "Etçil: küçük canlı ve donuk yemler"], ["Üreme", "Mağarada yumurtlayan; dişi bakar"], ["Köken", "Bolivya, Brezilya, Paraguay, Arjantin (Paraguay–Paraná havzası)"], ["Ömür", "3–5 yıl"], ["Özellikler", "Yüksek sırt yüzgeci"]]'::jsonb,array['apistogramma trifasciata','trifasciata','three striped apisto','apisto','apistogramma']::text[],false,'','[{"r": 600, "lat": -18, "lng": -57, "label": "Paraguay–Paraná havzası (Pantanal)"}]'::jsonb,null,'published'),
('apistogramma-viejita','Apistogramma viejita','Apistogramma viejita','guney-amerika','fish','Orta','Barışçıl, harem','Kolombiya''nın Meta havzasından, erkeklerinde kırmızı tonlu dudak ve yüzgeç kenarlarıyla öne çıkan bir Apistogramma. Hobide "viejita" adıyla satılan balıkların bir kısmı A. macmasteri ile karışıktır.','[["Yetişkin boy", "Erkek 6–7 cm, dişi 4–5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–6.5"], ["Min. akvaryum", "54 L"], ["Huy", "Barışçıl; 1 erkek + 2–3 dişi"], ["Beslenme", "Etçil: küçük canlı ve donuk yemler"], ["Üreme", "Mağarada yumurtlayan; dişi bakar"], ["Köken", "Kolombiya, Rio Meta havzası"], ["Ömür", "3–5 yıl"], ["Özellikler", "Kırmızı dudak ve yüzgeç kenarları"]]'::jsonb,array['apistogramma viejita','viejita','apisto','apistogramma']::text[],false,'','[{"r": 300, "lat": 4.2, "lng": -71.5, "label": "Rio Meta havzası"}]'::jsonb,null,'published'),
('neolamprologus-pulcher','Daffodil Prenses','Neolamprologus pulcher','tanganyika','fish','Orta','Koloni hâlinde, bölgeci','Prenses ciklide (N. brichardi) çok benzeyen, sarımsı tonları ve lir biçimli kuyruğuyla "Daffodil" adıyla bilinen bir Tanganyika ciklidi. Büyük aile koloniler kurar; önceki yavrular yeni yavruların korunmasına yardım eder.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "8.0–9.0"], ["Min. akvaryum", "100 L"], ["Huy", "Koloni içinde barışçıl, yabancılara karşı bölgeci"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Mağarada yumurtlayan; koloni birlikte bakar"], ["Köken", "Tanganyika Gölü güneyi (Zambiya, Tanzanya)"], ["Ömür", "8–10 yıl"], ["Özellikler", "Yardımcılı (kooperatif) üreme"]]'::jsonb,array['daffodil','neolamprologus pulcher','pulcher','prenses','daffodil cichlid','neolamprologus']::text[],false,'','[{"r": 200, "lat": -8.5, "lng": 31, "label": "Tanganyika Gölü güneyi"}]'::jsonb,'N. brichardi ile çok yakın akrabadır; bazı kaynaklar ikisini aynı tür olarak ele alır.','published'),
('hemigrammus-pulcher','Garnet Tetra (Pretty Tetra)','Hemigrammus pulcher','characiformlar','fish','Kolay','Barışçıl, sürü','Kuyruk sapındaki siyah leke ve gözünün üstündeki kırmızı parıltıyla tanınan, Peru Amazonu''ndan gelen dayanıklı bir tetra. 8+ bireylik sürüde en güzel rengini verir.','[["Yetişkin boy", "4–5 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk ve canlı küçük yemler"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Peru, Amazon havzası (Iquitos çevresi)"], ["Ömür", "4–6 yıl"], ["Özellikler", "Dayanıklı, topluluk tankına uygun"]]'::jsonb,array['garnet tetra','pretty tetra','hemigrammus pulcher','pulcher tetra','tetra']::text[],false,'','[{"r": 300, "lat": -3.8, "lng": -73.3, "label": "Iquitos çevresi"}]'::jsonb,null,'published'),
('moenkhausia-oligolepis','Gözlüklü Tetra (Glass Tetra)','Moenkhausia oligolepis','characiformlar','fish','Kolay','Barışçıl ama hızlı ve obur','Kırmızı üst göz kenarı ve kuyruk sapındaki siyah lekesiyle bilinen iri, gümüşi bir tetra. Hızlı yüzer ve obur yer; uzun yüzgeçli sakin balıklarla tutulmamalıdır.','[["Yetişkin boy", "8–12 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl; 6+ sürü; yüzgeç ısırabilir"], ["Beslenme", "Hepçil: granül, donuk yem, sebze"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Guyana, Surinam ve Amazon havzası"], ["Ömür", "5–8 yıl"], ["Özellikler", "İri ve dayanıklı tetra"]]'::jsonb,array['glass tetra','gözlüklü tetra','moenkhausia oligolepis','oligolepis','moenkhausia','tetra']::text[],false,'','[{"r": 500, "lat": 4.5, "lng": -57, "label": "Guyana ve Surinam"}, {"r": 500, "lat": -3, "lng": -60, "label": "Orta Amazon"}]'::jsonb,null,'published'),
('nematobrycon-lacortei','Gökkuşağı Tetra (Rainbow Tetra)','Nematobrycon lacortei','characiformlar','fish','Orta','Barışçıl, sürü','İmparator tetranın (N. palmeri) yakın akrabası; erkeklerinde kırmızı göz ve gövde boyunca gökkuşağı yansımaları vardır. Kolombiya''nın Pasifik kıyısındaki nehirlerden gelir.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "5.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk ve canlı küçük yemler"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Kolombiya, Río San Juan havzası"], ["Ömür", "4–6 yıl"], ["Özellikler", "Kırmızı gözler, gökkuşağı yansımaları"]]'::jsonb,array['rainbow tetra','gökkuşağı tetra','nematobrycon lacortei','lacortei','tetra']::text[],false,'','[{"r": 200, "lat": 4.5, "lng": -76.6, "label": "Río San Juan havzası"}]'::jsonb,null,'published'),
('chilodus-punctatus','Benekli Baş Aşağı Tetra (Spotted Headstander)','Chilodus punctatus','characiformlar','fish','Orta','Barışçıl','Başı aşağı eğik yüzmesi ve gövdesindeki benek sıralarıyla tanınan ilginç bir karasin; yüzerken hafif "tıklama" sesleri çıkarabilir. Yumuşak su ve bol bitki ister.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.5–7.0"], ["Min. akvaryum", "120 L"], ["Huy", "Barışçıl; 4+ grup"], ["Beslenme", "Hepçil: alg, sebze, küçük omurgasızlar"], ["Üreme", "Yumurtlayan"], ["Köken", "Güney Amerika kuzeyi (Guyana, Orinoco, Rio Negro)"], ["Ömür", "5–8 yıl"], ["Özellikler", "Baş aşağı yüzer"]]'::jsonb,array['spotted headstander','chilodus punctatus','chilodus','baş aşağı balığı','headstander']::text[],false,'','[{"r": 500, "lat": 5, "lng": -59, "label": "Guyana"}, {"r": 400, "lat": 2, "lng": -66, "label": "Orinoco ve Rio Negro"}]'::jsonb,null,'published'),
('nannostomus-trifasciatus','Üç Bantlı Kalem Balığı','Nannostomus trifasciatus','characiformlar','fish','Orta','Barışçıl, sürü','Gövdesinde üç koyu bant ve yüzgeç diplerinde kırmızı lekeler bulunan, en renkli kalem balıklarından. Gece desenini değiştirip benekli bir görünüme bürünür.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "5.0–7.0"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: küçük granül, donuk ve canlı küçük yemler"], ["Üreme", "Yumurtlayan"], ["Köken", "Amazon havzası, Rio Negro ve Guyana"], ["Ömür", "5 yıl"], ["Özellikler", "Gece deseni değişir"]]'::jsonb,array['three lined pencilfish','üç bantlı kalem','nannostomus trifasciatus','trifasciatus','kalem balığı','pencilfish']::text[],false,'','[{"r": 500, "lat": -2, "lng": -62, "label": "Orta Amazon ve Rio Negro"}]'::jsonb,null,'published'),
('nannostomus-mortenthaleri','Kızıl Kalem Balığı (Coral Red Pencilfish)','Nannostomus mortenthaleri','characiformlar','fish','Orta','Barışçıl; erkekler arası rekabet','Erkeklerinin neredeyse tamamen mercan kırmızısı olduğu, Peru''dan gelen küçük bir kalem balığı. Erkekler kendi aralarında zararsız çekişmeler yapar; yoğun bitkili, loş tanklarda en iyi rengini verir.','[["Yetişkin boy", "3.5–4.5 cm"], ["Sıcaklık", "24–27 °C"], ["pH", "5.0–6.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl; erkekler arası kısa çekişmeler"], ["Beslenme", "Etçil ağırlıklı: küçük canlı ve donuk yemler"], ["Üreme", "Yumurtlayan"], ["Köken", "Peru, Nanay Nehri havzası"], ["Ömür", "3–5 yıl"], ["Özellikler", "Mercan kırmızısı erkekler"]]'::jsonb,array['coral red pencilfish','kızıl kalem','nannostomus mortenthaleri','mortenthaleri','kalem balığı','pencilfish']::text[],false,'','[{"r": 150, "lat": -3.8, "lng": -73.6, "label": "Nanay Nehri (Iquitos çevresi)"}]'::jsonb,null,'published'),
('danio-albolineatus','İnci Danio (Pearl Danio)','Danio albolineatus','danio-rasboralar','fish','Kolay','Barışçıl, sürü','Sedef gibi parlayan, ışığa göre mavi-pembe yansımalar veren hareketli bir danio. Zebra danio kadar dayanıklıdır ve serin suya da uyum sağlar.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Güneydoğu Asya (Myanmar, Tayland, Laos)"], ["Ömür", "3–5 yıl"], ["Özellikler", "Sedef parlaklığı, çok hareketli"]]'::jsonb,array['pearl danio','inci danio','danio albolineatus','albolineatus','danio']::text[],false,'','[{"r": 600, "lat": 18, "lng": 99, "label": "Myanmar, Tayland ve Laos"}]'::jsonb,null,'published'),
('danio-kyathit','Kyathit Danio','Danio kyathit','danio-rasboralar','fish','Kolay','Barışçıl, sürü','Myanmar''ın kuzeyinden, benekli ve çizgili iki formuyla bilinen küçük bir danio; "orange finned zebra danio" adıyla da satılır. Erkeklerinin yüzgeçleri turuncu-kırmızıdır.','[["Yetişkin boy", "4 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "54 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Kuzey Myanmar (Myitkyina çevresi)"], ["Ömür", "3–5 yıl"], ["Özellikler", "Turuncu yüzgeçler"]]'::jsonb,array['kyathit','danio kyathit','orange finned danio','ocelot danio','danio']::text[],false,'','[{"r": 150, "lat": 25.4, "lng": 97.4, "label": "Myitkyina çevresi"}]'::jsonb,null,'published'),
('danio-dangila','Bıyıklı Danio (Moustached Danio)','Danio dangila','danio-rasboralar','fish','Kolay','Barışçıl, sürü','Uzun bıyıkları ve gövdesindeki halka biçimli beneklerle tanınan, danioların en irilerinden. Geniş yüzme alanı ve akıntılı, oksijeni bol su sever.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "18–25 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "160 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Hindistan, Nepal, Bangladeş, Butan (Himalaya etekleri)"], ["Ömür", "5 yıl"], ["Özellikler", "Uzun bıyıklar, halka benekler"]]'::jsonb,array['moustached danio','bıyıklı danio','danio dangila','dangila','danio']::text[],false,'','[{"r": 500, "lat": 26.5, "lng": 88, "label": "Himalaya eteklerindeki akarsular"}]'::jsonb,null,'published'),
('sawbwa-resplendens','Sawbwa Barb','Sawbwa resplendens','danio-rasboralar','fish','Orta','Barışçıl, sürü','Pulsuz, gümüşi-mavi gövdesi ve erkeklerinde kırmızı burun ile kuyruk uçlarıyla tanınan, yalnızca Myanmar''daki Inle Gölü''ne özgü küçük bir sazangil. Sert ve serin suyu sever.','[["Yetişkin boy", "3.5 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "54 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk ve canlı küçük yemler"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Myanmar, Inle Gölü"], ["Ömür", "3–4 yıl"], ["Özellikler", "Pulsuz gövde, kırmızı burun"]]'::jsonb,array['sawbwa','sawbwa resplendens','asian rummynose','inle','barb']::text[],false,'Doğal yaşam alanı (Inle Gölü) tehdit altındadır; üretim bireyleri tercih edilmeli.','[{"r": 30, "lat": 20.55, "lng": 96.9, "label": "Inle Gölü"}]'::jsonb,null,'published'),
('rasbora-kalochroma','Palyaço Rasbora (Clown Rasbora)','Rasbora kalochroma','danio-rasboralar','fish','Orta','Barışçıl, sürü; ürkek','Turuncu-pembe gövdesinde iki büyük koyu leke bulunan, Malezya ve Endonezya''nın turbalık siyah sularından gelen iri bir rasbora. Ürkek olduğundan kalabalık sürüde ve loş ortamda daha iyi renk verir.','[["Yetişkin boy", "8–10 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: granül, donuk ve canlı yemler"], ["Üreme", "Yumurtlayan"], ["Köken", "Malezya, Sumatra ve Borneo"], ["Ömür", "5 yıl"], ["Özellikler", "Siyah su, iki büyük leke"]]'::jsonb,array['clown rasbora','palyaço rasbora','rasbora kalochroma','kalochroma','rasbora']::text[],false,'','[{"r": 400, "lat": 1, "lng": 103, "label": "Malay Yarımadası ve Sumatra"}, {"r": 300, "lat": 0.5, "lng": 112, "label": "Borneo"}]'::jsonb,null,'published'),
('pethia-gelius','Altın Cüce Barb','Pethia gelius','sazangiller','fish','Kolay','Barışçıl, sürü','Altın-turuncu gövdesindeki koyu lekelerle tanınan, Hindistan ve Bangladeş''ten gelen en küçük barblardan. Serin suya dayanıklıdır; nano akvaryumlara uygundur.','[["Yetişkin boy", "3–4 cm"], ["Sıcaklık", "18–25 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "40 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: mikro granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurtaları yaprak altına yapıştırır)"], ["Köken", "Hindistan ve Bangladeş (Ganj–Brahmaputra havzası)"], ["Ömür", "3–4 yıl"], ["Özellikler", "Nano barb, serin suya dayanıklı"]]'::jsonb,array['golden dwarf barb','altın cüce barb','pethia gelius','puntius gelius','gelius','barb']::text[],false,'','[{"r": 600, "lat": 24, "lng": 89, "label": "Ganj–Brahmaputra havzası"}]'::jsonb,'Eski adları Puntius gelius ve Barbus gelius.','published'),
('pethia-nigrofasciata','Siyah Yakut Barb (Black Ruby Barb)','Pethia nigrofasciata','sazangiller','fish','Kolay','Barışçıl, sürü','Erkekleri üreme döneminde koyu kırmızı baş ve siyah gövdeye bürünen, Sri Lanka''ya özgü bir barb. Sumatra barbına göre çok daha sakindir.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: granül, sebze, donuk yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Sri Lanka (güneybatı yağmur ormanı dereleri)"], ["Ömür", "5 yıl"], ["Özellikler", "Erkeklerde koyu kırmızı-siyah üreme rengi"]]'::jsonb,array['black ruby barb','siyah yakut barb','pethia nigrofasciata','puntius nigrofasciatus','nigrofasciata','barb']::text[],false,'Doğada nesli tehlike altındadır; üretim bireyleri tercih edilmeli.','[{"r": 60, "lat": 6.6, "lng": 80.4, "label": "Güneybatı Sri Lanka"}]'::jsonb,'Eski adları Puntius nigrofasciatus ve Barbus nigrofasciatus.','published'),
('pethia-stoliczkana','Stoliczka Barb','Pethia stoliczkana','sazangiller','fish','Kolay','Barışçıl, sürü','Rosy barba benzeyen ama daha küçük, sırt yüzgecinde kırmızı-siyah bant ve gövdesinde iki siyah lekesi olan bir barb. Myanmar ve Tayland''dan gelir; Pethia ticto ile sık karıştırılır.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "20–26 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ sürü"], ["Beslenme", "Hepçil: granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurta saçan)"], ["Köken", "Myanmar ve Tayland (Irrawaddy, Salween havzaları)"], ["Ömür", "5 yıl"], ["Özellikler", "İki siyah leke, kırmızı sırt yüzgeci"]]'::jsonb,array['stoliczka barb','pethia stoliczkana','puntius stoliczkanus','barbus stoliczkanus','ticto barb','barb']::text[],false,'','[{"r": 500, "lat": 19, "lng": 97, "label": "Irrawaddy ve Salween havzaları"}]'::jsonb,'Eski adları Barbus stoliczkanus ve Puntius stoliczkanus; hobide Pethia ticto ile sık karıştırılır.','published'),
('desmopuntius-rhomboocellatus','Yılan Derisi Barb (Snakeskin Barb)','Desmopuntius rhomboocellatus','sazangiller','fish','Orta','Barışçıl, sürü','Gövdesindeki elmas biçimli koyu halkalarla "yılan derisi" görünümlü, Borneo''nun turbalık siyah sularından gelen bir barb. Yumuşak, asidik su ve loş ışık ister.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.5–6.5"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; 8+ sürü"], ["Beslenme", "Hepçil: granül, donuk ve canlı yemler"], ["Üreme", "Yumurtlayan"], ["Köken", "Endonezya, Kalimantan (Borneo)"], ["Ömür", "5 yıl"], ["Özellikler", "Siyah su, halka desen"]]'::jsonb,array['snakeskin barb','yılan derisi barb','desmopuntius rhomboocellatus','puntius rhomboocellatus','rhomboocellatus','barb']::text[],false,'','[{"r": 300, "lat": -1.5, "lng": 113, "label": "Orta ve Batı Kalimantan"}]'::jsonb,'Eski adları Puntius rhomboocellatus ve Barbus rhomboocellatus.','published'),
('rhodeus-ocellatus','Pembe Acı Balık (Rosy Bitterling)','Rhodeus ocellatus','sazangiller','fish','Orta','Barışçıl','Erkekleri üreme döneminde pembe-mor renge bürünen, yumurtalarını tatlı su midyelerinin içine bırakan ilginç bir Doğu Asya balığı. Serin suyu sever; üretimi için canlı midye gerekir.','[["Yetişkin boy", "5–7 cm"], ["Sıcaklık", "10–24 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "80 L"], ["Huy", "Barışçıl; erkekler üremede midyeyi korur"], ["Beslenme", "Hepçil: granül, sebze, donuk yem"], ["Üreme", "Yumurtlayan (yumurtaları midyenin içine bırakır)"], ["Köken", "Çin, Kore, Japonya ve Tayvan"], ["Ömür", "3–5 yıl"], ["Özellikler", "Soğuk su, midye ile ortak üreme"]]'::jsonb,array['rosy bitterling','acı balık','rhodeus ocellatus','bitterling','rhodeus']::text[],false,'Üretim için yaşayan tatlı su midyesi gerekir. Doğaya bırakılmamalıdır; yeni bölgelerde istilacı olabilir.','[{"r": 900, "lat": 30, "lng": 115, "label": "Doğu Çin"}, {"r": 300, "lat": 36, "lng": 128, "label": "Kore Yarımadası"}]'::jsonb,null,'published'),
('botia-lohachata','Yoyo Loach','Botia lohachata','loachlar','fish','Orta','Hareketli, grup hâlinde','Gövdesindeki koyu desenin "YOYO" harflerine benzemesiyle ünlenen hareketli bir loach. Salyangozları avlar; 5+ bireylik grup hâlinde ve bol saklanma alanıyla tutulmalıdır.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Grup içinde itişen; diğer türlerle barışçıl"], ["Beslenme", "Hepçil: salyangoz, batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Hindistan, Nepal, Bangladeş, Pakistan (Ganj–Brahmaputra)"], ["Ömür", "10–15 yıl"], ["Özellikler", "Salyangoz yer, YOYO deseni"]]'::jsonb,array['yoyo loach','botia lohachata','lohachata','botia','loach','pakistani loach']::text[],false,'Gözlerinin altında katlanır dikenleri vardır; ağla yakalarken takılabilir, kap ile almak daha güvenlidir.','[{"r": 700, "lat": 25.5, "lng": 85, "label": "Ganj–Brahmaputra havzası"}]'::jsonb,null,'published'),
('botia-rostrata','Merdiven Loach (Ladder Loach)','Botia rostrata','loachlar','fish','Orta','Hareketli, grup hâlinde','Gövdesindeki merdiveni andıran zeytin-sarı desenle tanınan, yoyo loachun yakın akrabası. Hindistan ve Bangladeş''in kuzeydoğusundan gelir.','[["Yetişkin boy", "10–12 cm"], ["Sıcaklık", "23–27 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "150 L"], ["Huy", "Grup içinde itişen; diğer türlerle barışçıl"], ["Beslenme", "Hepçil: salyangoz, batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Hindistan (Assam) ve Bangladeş"], ["Ömür", "10+ yıl"], ["Özellikler", "Merdiven deseni"]]'::jsonb,array['ladder loach','merdiven loach','botia rostrata','rostrata','gangetic loach','botia','loach']::text[],false,'Gözlerinin altında dikenleri vardır; ağla yakalarken dikkatli ol.','[{"r": 400, "lat": 25.5, "lng": 90, "label": "Brahmaputra havzası"}]'::jsonb,null,'published'),
('botia-dario','Bengal Loach','Botia dario','loachlar','fish','Orta','Hareketli, grup hâlinde','Sarı zemin üzerindeki eğik siyah bantlarıyla tanınan, Botia cinsinin en renkli türlerinden biri. 5+ bireylik grup ve bol saklanma alanı ister.','[["Yetişkin boy", "12–15 cm"], ["Sıcaklık", "23–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Grup içinde itişen; diğer türlerle barışçıl"], ["Beslenme", "Hepçil: salyangoz, batan granül, donuk yem"], ["Üreme", "Yumurtlayan (akvaryumda nadir)"], ["Köken", "Hindistan, Bangladeş, Butan (Brahmaputra havzası)"], ["Ömür", "10+ yıl"], ["Özellikler", "Sarı-siyah bantlar"]]'::jsonb,array['bengal loach','queen loach','botia dario','dario loach','botia','loach']::text[],false,'Gözlerinin altında dikenleri vardır; ağla yakalarken dikkatli ol.','[{"r": 450, "lat": 26, "lng": 90, "label": "Brahmaputra havzası"}]'::jsonb,null,'published'),
('brochis-splendens','Zümrüt Corydoras (Emerald Cory)','Brochis splendens','kedi-baliklari','fish','Kolay','Barışçıl, grup hâlinde','Zümrüt yeşili metalik gövdesiyle corydorasların en irilerinden biri. Yumuşak kum zemin üzerinde grup hâlinde gezer ve yere düşen yemleri temizler.','[["Yetişkin boy", "6–8 cm"], ["Sıcaklık", "22–28 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "100 L"], ["Huy", "Barışçıl; 5+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurtaları cama ve yapraklara yapıştırır)"], ["Köken", "Amazon havzası (Brezilya, Peru, Ekvador, Kolombiya)"], ["Ömür", "10+ yıl"], ["Özellikler", "Metalik yeşil, iri cory"]]'::jsonb,array['emerald cory','zümrüt corydoras','brochis splendens','corydoras splendens','brochis','corydoras','çöpçü']::text[],false,'Bıyıklarının zarar görmemesi için kum ya da çok yumuşak, yuvarlak taneli zemin şart.','[{"r": 900, "lat": -4, "lng": -68, "label": "Batı ve orta Amazon havzası"}]'::jsonb,'Uzun süre Brochis splendens olarak bilindi, bir dönem Corydoras splendens adıyla geçti; 2024 revizyonuyla yeniden Brochis cinsine alındı.','published'),
('corydoras-schwartzi','Schwartz Corydoras','Corydoras schwartzi','kedi-baliklari','fish','Kolay','Barışçıl, grup hâlinde','Gövdesinde sıra sıra koyu benekler ve sırt yüzgecinde siyah leke bulunan, Brezilya''nın Purus Nehri havzasından gelen bir corydoras. Satışta benzer görünüşlü türlerle sık karıştırılır.','[["Yetişkin boy", "4.5–5.5 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurtaları cama yapıştırır)"], ["Köken", "Brezilya, Rio Purus havzası"], ["Ömür", "5–10 yıl"], ["Özellikler", "Benekli desen"]]'::jsonb,array['schwartzi','corydoras schwartzi','hoplisoma schwartzi','schwartz cory','corydoras','çöpçü']::text[],false,'Kum zemin önerilir.','[{"r": 400, "lat": -7, "lng": -65, "label": "Rio Purus havzası"}]'::jsonb,'2024''te yayımlanan Corydoras revizyonuyla Hoplisoma cinsine taşındı; güncel kaynaklarda Hoplisoma schwartzi olarak geçer.','published'),
('corydoras-weitzmani','Weitzman Corydoras','Corydoras weitzmani','kedi-baliklari','fish','Zor','Barışçıl, grup hâlinde','Peru''nun Cusco bölgesindeki And eteklerinden, altın-sarı gövdesinde koyu eyer lekeleriyle nadir görülen bir corydoras. Serin, temiz ve oksijeni bol su ister.','[["Yetişkin boy", "4–5 cm"], ["Sıcaklık", "20–24 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan"], ["Köken", "Peru, Cusco (Urubamba havzası)"], ["Ömür", "5–10 yıl"], ["Özellikler", "Serin su, eyer lekeleri"]]'::jsonb,array['weitzmani','corydoras weitzmani','hoplisoma weitzmani','weitzman cory','corydoras','çöpçü']::text[],true,'Yüksek sıcaklığa dayanıksızdır; 25 °C üstünde strese girer.','[{"r": 200, "lat": -12.9, "lng": -72.5, "label": "Urubamba havzası (Cusco)"}]'::jsonb,'2024''te yayımlanan Corydoras revizyonuyla Hoplisoma cinsine taşındı; güncel kaynaklarda Hoplisoma weitzmani olarak geçer.','published'),
('corydoras-arcuatus','Kemerli Corydoras (Skunk Cory)','Corydoras arcuatus','kedi-baliklari','fish','Kolay','Barışçıl, grup hâlinde','Burnundan kuyruğuna kadar uzanan tek bir siyah kemer çizgisiyle tanınan corydoras; "skunk cory" adıyla satılır. Dayanıklıdır ve topluluk akvaryumlarına uygundur.','[["Yetişkin boy", "5 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan (yumurtaları cama yapıştırır)"], ["Köken", "Peru, Brezilya ve Ekvador (yukarı Amazon)"], ["Ömür", "5–10 yıl"], ["Özellikler", "Siyah kemer çizgisi"]]'::jsonb,array['skunk cory','kemerli corydoras','corydoras arcuatus','arcuatus','corydoras','çöpçü']::text[],false,'Kum zemin önerilir.','[{"r": 600, "lat": -4, "lng": -72, "label": "Yukarı Amazon havzası"}]'::jsonb,null,'published'),
('corydoras-gossei','Gossei Corydoras','Corydoras gossei','kedi-baliklari','fish','Orta','Barışçıl, grup hâlinde','Gri-mavi gövdesi ve parlak turuncu yüzgeçleriyle hemen ayırt edilen bir corydoras. Brezilya-Bolivya sınırındaki Mamoré ve Guaporé nehirlerinden gelir.','[["Yetişkin boy", "5–6 cm"], ["Sıcaklık", "22–26 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "60 L"], ["Huy", "Barışçıl; 6+ grup"], ["Beslenme", "Hepçil: batan granül, donuk yem"], ["Üreme", "Yumurtlayan"], ["Köken", "Brezilya ve Bolivya (Rio Mamoré, Rio Guaporé)"], ["Ömür", "5–10 yıl"], ["Özellikler", "Turuncu yüzgeçler"]]'::jsonb,array['gossei','corydoras gossei','gosse cory','corydoras','çöpçü']::text[],false,'Kum zemin önerilir.','[{"r": 300, "lat": -12, "lng": -64.5, "label": "Rio Mamoré ve Rio Guaporé"}]'::jsonb,null,'published'),
('betta-coccina','Şarap Kırmızısı Betta (Betta coccina)','Betta coccina','labirentliler','fish','Zor','Barışçıl, çift hâlinde','Şarap kırmızısı gövdesi ve yanındaki yeşil parlak lekesiyle tanınan küçük, köpük yuvası yapan bir yabani betta. Malezya ve Sumatra''nın turbalık siyah sularından gelir; çok yumuşak ve asidik su ister.','[["Yetişkin boy", "4–5 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "4.0–6.0"], ["Min. akvaryum", "30 L (çift)"], ["Huy", "Barışçıl; çift ya da küçük grup"], ["Beslenme", "Etçil: küçük canlı ve donuk yemler"], ["Üreme", "Köpük yuvası yapar"], ["Köken", "Malezya (Johor) ve Sumatra"], ["Ömür", "3–5 yıl"], ["Özellikler", "Siyah su, yabani betta"]]'::jsonb,array['betta coccina','coccina','wine red betta','yabani betta','betta']::text[],true,'Kapak şart; labirent organıyla nefes aldığı için su üstündeki hava sıcak ve nemli olmalı.','[{"r": 200, "lat": 1.9, "lng": 103.3, "label": "Johor (Malezya)"}, {"r": 300, "lat": -1.5, "lng": 103.5, "label": "Sumatra"}]'::jsonb,null,'published'),
('dario-hysginon','Dario hysginon','Dario hysginon','diger-baliklar','fish','Orta','Erkekler bölgeci','Kırmızı badise (Dario dario) benzeyen ama gövdesi kırmızı bantlı, biraz daha iri küçük bir badid. Yoğun bitkili nano akvaryumlarda canlı yemlerle beslenir.','[["Yetişkin boy", "2.5–3 cm"], ["Sıcaklık", "20–25 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "30 L"], ["Huy", "Erkekler arası bölgeci; 1 erkek + 2–3 dişi"], ["Beslenme", "Etçil: küçük canlı ve donuk yemler"], ["Üreme", "Yaprak ya da mağaraya yumurtlayan; erkek bakar"], ["Köken", "Myanmar–Hindistan sınır bölgesi (Chindwin havzası)"], ["Ömür", "3 yıl"], ["Özellikler", "Nano balık, kırmızı bantlar"]]'::jsonb,array['dario hysginon','hysginon','badis','dario','scarlet badis']::text[],false,'Kuru yemi çoğu zaman kabul etmez; canlı ya da donuk küçük yemler gerekir.','[{"r": 250, "lat": 24, "lng": 94.5, "label": "Chindwin havzası"}]'::jsonb,null,'published'),
('tetraodon-mbu','Dev Kongo Balonu (Mbu Puffer)','Tetraodon mbu','diger-baliklar','fish','Zor','Yalnız tutulmalı','60 cm''yi aşabilen, dünyanın en büyük tatlı su balonu. Zeki ve sahibini tanıyan bir balıktır; ancak çok büyük bir akvaryum, güçlü filtre ve sert kabuklu yemler ister.','[["Yetişkin boy", "60–75 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "2000 L+"], ["Huy", "Yalnız tutulmalı"], ["Beslenme", "Etçil: midye, salyangoz, karides, yengeç"], ["Üreme", "Yumurtlayan (akvaryumda kaydı yok)"], ["Köken", "Kongo Nehri ve Tanganyika Gölü"], ["Ömür", "10–20 yıl"], ["Özellikler", "En büyük tatlı su balonu"]]'::jsonb,array['mbu puffer','mbu','tetraodon mbu','dev balon','balon balığı','puffer']::text[],false,'Çok büyük hacim ve çok güçlü filtre şart. Gagasının aşınması için kabuklu yemler gerekir. Isırığı tehlikelidir.','[{"r": 800, "lat": -3, "lng": 22, "label": "Kongo Havzası"}, {"r": 200, "lat": -6, "lng": 29.5, "label": "Tanganyika Gölü"}]'::jsonb,null,'published'),
('tetraodon-lineatus','Fahaka Balonu','Tetraodon lineatus','diger-baliklar','fish','Zor','Çok saldırgan, yalnız','Nil ve Batı Afrika nehirlerinden, gövdesindeki sarı-kahverengi çizgilerle tanınan iri ve saldırgan bir balon. Tek başına tutulmalı, sert kabuklu yemlerle dişlerinin aşınması sağlanmalıdır.','[["Yetişkin boy", "30–45 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.0–8.0"], ["Min. akvaryum", "500 L"], ["Huy", "Çok saldırgan; yalnız tutulmalı"], ["Beslenme", "Etçil: midye, salyangoz, karides"], ["Üreme", "Yumurtlayan"], ["Köken", "Nil, Çad Gölü, Nijer ve Volta havzaları"], ["Ömür", "10+ yıl"], ["Özellikler", "Tamamen tatlı su, iri balon"]]'::jsonb,array['fahaka','fahaka puffer','tetraodon lineatus','nil balonu','balon balığı','puffer']::text[],false,'Akvaryumdaki her canlıyı öldürebilir; tek başına tutulmalı. Isırığı tehlikelidir.','[{"r": 1200, "lat": 13, "lng": 31, "label": "Nil havzası"}, {"r": 700, "lat": 12, "lng": 2, "label": "Nijer ve Volta havzaları"}, {"r": 300, "lat": 13, "lng": 14.5, "label": "Çad Gölü"}]'::jsonb,null,'published'),
('dichotomyctere-fluviatilis','Yeşil Nehir Balonu','Dichotomyctere fluviatilis','aci-su','fish','Orta','Saldırgan','Yeşil benekli balona (D. nigroviridis) çok benzeyen, Güney ve Güneydoğu Asya''nın acı sularından gelen bir balon. Gençken tatlı suda yaşayabilse de erişkin olunca acı su ister.','[["Yetişkin boy", "15–17 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "7.5–8.5"], ["Min. akvaryum", "150 L"], ["Huy", "Saldırgan; yüzgeç ısırır"], ["Beslenme", "Etçil: salyangoz, midye, karides"], ["Üreme", "Yumurtlayan"], ["Köken", "Hindistan, Sri Lanka, Bangladeş, Myanmar"], ["Ömür", "10 yıl"], ["Özellikler", "Acı su balonu"]]'::jsonb,array['fluviatilis','dichotomyctere fluviatilis','tetraodon fluviatilis','green puffer','yeşil balon','balon balığı','puffer']::text[],false,'Erişkinler acı su ister (yoğunluk yaklaşık 1.005–1.010). Gagasının aşınması için kabuklu yem şart.','[{"r": 900, "lat": 18, "lng": 85, "label": "Hindistan ve Bangladeş kıyıları"}, {"r": 250, "lat": 7.5, "lng": 80.7, "label": "Sri Lanka"}]'::jsonb,'Eski adı Tetraodon fluviatilis.','published'),
('pao-palembangensis','Palembang Balonu','Pao palembangensis','diger-baliklar','fish','Zor','Pusucu, yalnız','Gün boyu saklanıp avını pusuda bekleyen, kahverengi-sarı desenli bir Asya tatlı su balonu. Saatlerce hareketsiz durduğu için "tembel balon" diye de anılır.','[["Yetişkin boy", "15–20 cm"], ["Sıcaklık", "24–28 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Yalnız tutulmalı"], ["Beslenme", "Etçil: salyangoz, karides, balık eti"], ["Üreme", "Yumurtlayan"], ["Köken", "Endonezya (Sumatra, Borneo), Malezya, Tayland"], ["Ömür", "10 yıl"], ["Özellikler", "Pusucu, tamamen tatlı su"]]'::jsonb,array['palembang puffer','pao palembangensis','tetraodon palembangensis','palembangensis','balon balığı','puffer']::text[],false,'Ağzına sığan her balığı yer; yalnız tutulmalı.','[{"r": 500, "lat": -1.5, "lng": 105, "label": "Sumatra ve Borneo"}, {"r": 300, "lat": 7, "lng": 100.5, "label": "Tayland ve Malezya"}]'::jsonb,'Eski adı Tetraodon palembangensis.','published'),
('channa-asiatica','Asya Cüce Yılanbaşı','Channa asiatica','yilanbaslar','fish','Orta','Tür içi saldırgan','Kuyruk sapındaki gözlü leke ve gövdesindeki parlak beneklerle bilinen, Çin''in güneyi ve Tayvan''dan gelen bir yılanbaşı. Karın yüzgeci yoktur; serin suyu sever.','[["Yetişkin boy", "20–30 cm"], ["Sıcaklık", "15–25 °C"], ["pH", "6.0–7.5"], ["Min. akvaryum", "200 L"], ["Huy", "Tür içi saldırgan; ağzına sığanı yer"], ["Beslenme", "Etçil: balık eti, karides, solucan"], ["Üreme", "Ağızda kuluçka (erkek)"], ["Köken", "Güney Çin ve Tayvan"], ["Ömür", "8–10 yıl"], ["Özellikler", "Karın yüzgeci yok, serin su"]]'::jsonb,array['channa asiatica','asiatica','small snakehead','yılanbaşı','channa']::text[],false,'Kapak şart; zıplayıp kaçar. Doğaya bırakılmamalı.','[{"r": 600, "lat": 24, "lng": 112, "label": "Güney Çin"}, {"r": 150, "lat": 23.7, "lng": 121, "label": "Tayvan"}]'::jsonb,null,'published'),
('channa-maculata','Benekli Yılanbaşı (Blotched Snakehead)','Channa maculata','yilanbaslar','fish','Zor','Yırtıcı, yalnız','Çin''in güneyi ve Vietnam''dan gelen, 40 cm''yi aşabilen iri bir yılanbaşı. Serin suya dayanıklıdır; hızla büyür ve ağzına sığan her balığı yer.','[["Yetişkin boy", "30–50 cm"], ["Sıcaklık", "12–25 °C"], ["pH", "6.5–7.5"], ["Min. akvaryum", "400 L"], ["Huy", "Yırtıcı; yalnız tutulmalı"], ["Beslenme", "Etçil: balık eti, karides, solucan"], ["Üreme", "Yumurtlayan; çift yavrularını korur"], ["Köken", "Güney Çin, Vietnam ve Tayvan"], ["Ömür", "10+ yıl"], ["Özellikler", "Hızlı büyür, serin suya dayanıklı"]]'::jsonb,array['channa maculata','blotched snakehead','benekli yılanbaşı','yılanbaşı','channa']::text[],false,'Doğaya bırakılmamalı; Japonya ve Hawaii''de istilacı hâle gelmiştir. Kapak şart.','[{"r": 700, "lat": 23, "lng": 110, "label": "Güney Çin ve Kuzey Vietnam"}]'::jsonb,null,'published')
on conflict (slug) do nothing;

insert into public.species_forms (species_id, name, kind, origin, note, aliases, position, status)
select s.id, f.name, f.kind, f.origin, f.note, f.aliases, f.pos, 'published'
from (values
  ('carassius-auratus',0,'Comet','varyete','Akvaryum üretimi','Tek ve uzun kuyruklu, hızlı yüzen form; havuza uygundur.',array[]::text[]),
  ('carassius-auratus',1,'Shubunkin','varyete','Akvaryum üretimi','Mavi zeminli, kırmızı-siyah benekli (calico) tek kuyruklu form.',array[]::text[]),
  ('carassius-auratus',2,'Oranda','varyete','Akvaryum üretimi','Başında "wen" denen yumuşak doku büyümesi olan çift kuyruklu form.',array[]::text[]),
  ('carassius-auratus',3,'Ranchu','varyete','Akvaryum üretimi','Sırt yüzgeci olmayan, başı wen''li, tıknaz Japon formu.',array[]::text[]),
  ('carassius-auratus',4,'Lionhead','varyete','Akvaryum üretimi','Sırt yüzgeci olmayan, başı yoğun wen''li Çin formu.',array['Aslan başlı']::text[]),
  ('carassius-auratus',5,'Ryukin','varyete','Akvaryum üretimi','Omuz kısmı yüksek, çift kuyruklu form.',array[]::text[]),
  ('carassius-auratus',6,'Telescope','varyete','Akvaryum üretimi','Gözleri dışa doğru çıkık form; siyahına Black Moor denir.',array['Teleskop','Demekin','Black Moor']::text[]),
  ('carassius-auratus',7,'Bubble Eye','varyete','Akvaryum üretimi','Gözlerinin altında sıvı dolu keseler olan, sırt yüzgeçsiz form; kolay yaralanır.',array['Kabarcık göz']::text[]),
  ('carassius-auratus',8,'Pearlscale','varyete','Akvaryum üretimi','Pulları inci gibi kabarık, top gövdeli form.',array['İnci pullu']::text[]),
  ('carassius-auratus',9,'Celestial Eye','varyete','Akvaryum üretimi','Gözleri yukarı bakan, sırt yüzgeçsiz form.',array['Gökyüzü gözlü']::text[]),
  ('tropheus-duboisi',0,'Maswa','lokalite','Tanzanya, Maswa','Sarı bandı geniş, en sık görülen form.',array[]::text[]),
  ('tropheus-duboisi',1,'Kigoma','lokalite','Tanzanya, Kigoma','Beyaz-sarı bandı daha ince form.',array[]::text[]),
  ('amphiprion-percula',0,'Picasso','varyete','Akvaryum üretimi','Beyaz bantları birleşip düzensiz desen oluşturan hat.',array[]::text[]),
  ('amphiprion-percula',1,'Black Onyx','varyete','Akvaryum üretimi','Siyah tonları yoğun hat.',array['Onyx']::text[]),
  ('amphiprion-percula',2,'Platinum','varyete','Akvaryum üretimi','Gövdesi neredeyse tamamen beyaz hat.',array[]::text[]),
  ('pelvicachromis-pulcher',0,'Albino','varyete','Akvaryum üretimi','',array[]::text[]),
  ('pelvicachromis-taeniatus',0,'Moliwe','lokalite','Kamerun, Moliwe','',array[]::text[]),
  ('pelvicachromis-taeniatus',1,'Nyete','lokalite','Kamerun, Nyete','',array[]::text[]),
  ('pelvicachromis-taeniatus',2,'Wouri','lokalite','Kamerun, Wouri Nehri','',array[]::text[]),
  ('pelvicachromis-taeniatus',3,'Lokoundje','lokalite','Kamerun, Lokoundje Nehri','',array[]::text[]),
  ('pelvicachromis-taeniatus',4,'Dehane','lokalite','Kamerun, Dehane','',array[]::text[]),
  ('pelvicachromis-kribensis',0,'Kienke','lokalite','Kamerun, Kienke Nehri','',array[]::text[]),
  ('pelvicachromis-kribensis',1,'Lobe','lokalite','Kamerun, Lobe Nehri','',array[]::text[]),
  ('metriaclima-callainos',0,'White','varyete','Doğal form','Beyazımsı, açık renkli doğal form.',array['Pearl Zebra']::text[]),
  ('metriaclima-callainos',1,'Nkhata Bay','lokalite','Malawi, Nkhata Bay','',array[]::text[]),
  ('danio-kyathit',0,'Spotted','varyete','Doğal form','Benekli desenli form.',array['Benekli']::text[]),
  ('danio-kyathit',1,'Striped','varyete','Doğal form','Çizgili desenli form.',array['Çizgili']::text[]),
  ('channa-asiatica',0,'Platinum','varyete','Akvaryum üretimi','Açık, gümüşi-beyaz renkli hat.',array[]::text[])
) as f(slug, pos, name, kind, origin, note, aliases)
join public.species s on s.slug = f.slug
where not exists (select 1 from public.species_forms x where x.species_id = s.id and lower(x.name) = lower(f.name));

-- Makale ↔ tür bağlantıları (mevcut bağlantılar korunur)
update public.articles a set species_slugs = coalesce(a.species_slugs, '{}') || v.sp
from (values
  ('japon-baligi-fanusta-yasar-mi-en-eski-akvaryum-efsanelerinden-biri','carassius-auratus'),
  ('carinotetraodon-travancoricus-bezelye-kadar-karakteri-kocaman','carinotetraodon-travancoricus'),
  ('duboisi-benekli-yavruluktan-siyah-beyaz-eriskinlige','tropheus-duboisi'),
  ('elizabeth-cuce-cichlid-rio-negronun-hassas-mucevheri','apistogramma-elizabethae'),
  ('zebra-acara-nannacara-mi-ivanacara-mi','ivanacara-adoketa'),
  ('teleocichla-centrarchus-xingu-akintisina-gore-sekillenmis-cuce-cichlid','teleocichla-centrarchus'),
  ('congo-spotted-puffer-gercek-tatli-su-pufferi','tetraodon-schoutedeni'),
  ('red-eye-red-tail-puffer-pea-pufferin-daha-iri-kuzeni','carinotetraodon-irrubesco'),
  ('canara-pearlspot-hindistanin-tatli-su-etroplusu','etroplus-canarensis'),
  ('true-percula-clownfish-palyaco-baligi-anemon-ortakligi-gercekte-nasil-calisiyor','amphiprion-percula')
) as v(art, sp)
where a.slug = v.art and not (v.sp = any(coalesce(a.species_slugs, '{}')));

-- Etroplus maculatus: Glaser'daki güncel ad
update public.species set name_note = 'Son revizyonla Pseudetroplus cinsine taşındı; güncel kaynaklarda Pseudetroplus maculatus olarak geçer. Hobide hâlâ çoğunlukla Etroplus maculatus olarak bilinir.'
  where latin = 'Etroplus maculatus' and coalesce(name_note, '') = '';
update public.species set keywords = (select array_agg(distinct k) from unnest(coalesce(keywords, '{}') || array['pseudetroplus maculatus']) as k)
  where latin = 'Etroplus maculatus';
